ob=root.find('./ObjectData/Object[@name="CCX_Results"]');ids=[int(v.attrib['v']) for v in ob.findall('./Properties/Property[@name="NodeNumbers"]/IntegerList/I')];assert len(ids)==len(u) and len(ids)==len(set(ids))
