xx,yy,zz,xy,yz,xz=[fields['NodeStress'+n] for n in ['XX','YY','ZZ','XY','YZ','XZ']];vm=np.sqrt(.5*((xx-yy)**2+(yy-zz)**2+(zz-xx)**2)+3*(xy**2+yz**2+xz**2));vm_error=float(np.max(abs(vm-fields['vonMises'])));assert vm_error<1e-8
fig=plt.figure(figsize=(7,3.6));ax=fig.add_subplot(111,projection='3d');im=ax.scatter(*xyz.T,c=fields['vonMises'],s=4,cmap='viridis');fig.colorbar(im,ax=ax,shrink=.65,label='Saved von Mises (source units)');ax.set_box_aspect(np.maximum(np.ptp(xyz,axis=0),1));ax.set_axis_off();ax.view_init(25,-65);fig.tight_layout();fig.savefig(T/'frame-fem.png',dpi=200);plt.close(fig)
